    -- checks local too; calling the availability API again adds no evidence.
    local available = job.availability[to]
    if available == nil then available = job:Available(to) end
    if not available then return end
    local approach, exit = job.approachCosts[from], ProbeGroundCost(job, to, false)
    if exit == false then return end
    local lowerBound = approach + BOARDING_SECONDS + exit
    local best = job.best
    if lowerBound >= job.baseline or (best and lowerBound > best.estimatedSeconds) then return end
    local source, target = job:Position(from), job:Position(to)
    if source.instanceID ~= target.instanceID then return end

    local duration = job:Measured(record.signature) or record.path.durationSeconds
    if not Positive(duration) then duration = Distance(source, target) * 1.25 / 32 end
    local estimate = approach + duration + BOARDING_SECONDS + exit
    local quote = job:Quote(to, from)
    if quote then
        job.owner.probeAttempts[pair] = true
        return
    end
    -- A missing live price is unknown; it does not make the flight free.
    if job.live and job.currentNodeID == from then return end
    if Positive(estimate) and estimate < job.baseline
        and (not best or estimate < best.estimatedSeconds
            or (estimate == best.estimatedSeconds and tostring(record.id) < tostring(best.pathID))) then
        job.best = {
            kind = "verify_taxi", from = source, to = source, fromNodeID = from, toNodeID = to,
            pathID = record.id, estimatedSeconds = estimate, instruction = L["NAVIGATION_CONSULT_TAXI"],
